[CmdletBinding()] param([string]$InstallDirectory='',[switch]$PurgeData,[switch]$Force)
$ErrorActionPreference='Stop'; Set-StrictMode -Version Latest; . (Join-Path $PSScriptRoot 'Common.ps1'); if(-not $InstallDirectory){$InstallDirectory=Get-DefaultInstallRoot}; $InstallDirectory=[IO.Path]::GetFullPath($InstallDirectory)
Assert-Docker; $versionDirectory=Get-CurrentVersionDirectory $InstallDirectory; Invoke-Compose $InstallDirectory $versionDirectory @('down','--remove-orphans')
if($PurgeData){if(-not $Force){Stop-WithError 'Purging data and secrets is irreversible. Rerun with -PurgeData -Force'};$data=[IO.Path]::GetFullPath((Get-EnvValue (Join-Path $InstallDirectory '.env') 'MAINTAINER_DATA_DIR'));$prefix=$InstallDirectory.TrimEnd('\')+'\';if(-not $data.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)){Stop-WithError 'Refusing to purge data outside the installation root'};if(Test-Path $data){Remove-Item -LiteralPath $data -Recurse -Force};Remove-Item -LiteralPath (Join-Path $InstallDirectory '.env') -Force;Write-Host 'Application and persistent data removed. Version bundles and backups were preserved.'}else{Write-Host 'Containers removed. Data, secrets, bundles and backups were preserved.'}
